const __pageData = JSON.parse('{"title":"MySQL 8.4 MVCC 工程实践：Read View、版本链与一致性读","description":"","frontmatter":{"title":"MySQL 8.4 MVCC 工程实践：Read View、版本链与一致性读","date":"2026-08-10T00:00:00.000Z","category":"MySQL","cover":"/covers/backend.svg","tags":["mysql","innodb","mvcc","read-view","transaction"],"excerpt":"从 Read View、隐藏事务字段与 undo 版本链出发，讲清 RC、RR 的可见性差异，并把快照读、当前读、长事务治理落到真实订单场景。"},"headers":[],"relativePath":"posts/mysql-mvcc-read-view-engineering.md","filePath":"posts/mysql-mvcc-read-view-engineering.md","lastUpdated":1787128073000}');
